@page "/shipments"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>All Shipments</PageTitle>

<div class="container mt-4">
    <h2>📋 All Shipments</h2>

    <div class="row mb-3">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Filter by tracking number or destination..."
                   @bind="filterText" @bind:event="oninput" />
        </div>
        <div class="col-md-6 text-end">
            <button class="btn btn-primary" @onclick="ToggleCreateForm">
                @(showCreateForm ? "Cancel" : "➕ Create Shipment")
            </button>
        </div>
    </div>

    @if (showCreateForm)
    {
        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title">New Shipment</h5>
                <div class="row g-3">
                    <div class="col-md-4">
                        <label class="form-label">Tracking Number</label>
                        <input type="text" class="form-control" @bind="newShipment.TrackingNumber" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Origin</label>
                        <input type="text" class="form-control" @bind="newShipment.Origin" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Destination</label>
                        <input type="text" class="form-control" @bind="newShipment.Destination" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Customer Email</label>
                        <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Description</label>
                        <input type="text" class="form-control" @bind="newShipment.Description" />
                    </div>
                    <div class="col-md-2">
                        <label class="form-label">Weight (kg)</label>
                        <input type="number" step="0.1" class="form-control" @bind="newShipment.WeightKg" />
                    </div>
                    <div class="col-md-2">
                        <label class="form-label">Est. Delivery Days</label>
                        <input type="number" class="form-control" @bind="estimatedDays" />
                    </div>
                    <div class="col-12">
                        <button class="btn btn-success" @onclick="CreateShipment">Create</button>
                    </div>
                </div>
            </div>
        </div>
    }

    @if (shipments is null)
    {
        <p><em>Loading shipments...</em></p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Weight (kg)</th>
                        <th>Update Status</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><a href="/track/@s.TrackingNumber">@s.TrackingNumber</a></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                            <td>@s.WeightKg.ToString("F1")</td>
                            <td>
                                <select class="form-select form-select-sm" value="@((int)s.Status)"
                                        @onchange="e => UpdateStatus(s, e)">
                                    @foreach (ShipmentStatus status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@((int)status)">@status</option>
                                    }
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        @if (!FilteredShipments.Any())
        {
            <div class="alert alert-info">No shipments match your filter.</div>
        }
    }
</div>

@code {
    private List<Shipment>? shipments;
    private string filterText = string.Empty;
    private bool showCreateForm;
    private Shipment newShipment = new();
    private int estimatedDays = 5;

    private IEnumerable<Shipment> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrWhiteSpace(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ToggleCreateForm() => showCreateForm = !showCreateForm;

    private async Task CreateShipment()
    {
        newShipment.ShippedDate = DateTime.UtcNow;
        newShipment.EstimatedDelivery = DateTime.UtcNow.AddDays(estimatedDays);
        newShipment.Status = ShipmentStatus.Pending;
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments?.Add(created);
        newShipment = new Shipment();
        estimatedDays = 5;
        showCreateForm = false;
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
            if (newStatus == ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-warning text-dark",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@page "/track/{TrackingNumber}"
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2>🔍 Track a Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number..."
                       @bind="searchInput" @bind:event="oninput" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="Search">Search</button>
            </div>
        </div>
    </div>

    @if (loading)
    {
        <p><em>Searching...</em></p>
    }
    else if (searched && shipment is null)
    {
        <div class="alert alert-warning">
            <strong>Shipment not found.</strong> No shipment matches tracking number "<strong>@searchedNumber</strong>".
        </div>
    }
    else if (shipment is not null)
    {
        <div class="card shadow-sm mb-4">
            <div class="card-header bg-dark text-white">
                <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
            </div>
            <div class="card-body">
                <!-- Status Progress -->
                <div class="mb-4">
                    <h6>Status Progress</h6>
                    @{
                        var steps = new[] { ShipmentStatus.Pending, ShipmentStatus.PickedUp, ShipmentStatus.InTransit, ShipmentStatus.OutForDelivery, ShipmentStatus.Delivered };
                        var currentIndex = Array.IndexOf(steps, shipment.Status);
                        var isSpecial = shipment.Status == ShipmentStatus.Delayed || shipment.Status == ShipmentStatus.Returned;
                    }

                    @if (isSpecial)
                    {
                        <div class="alert @(shipment.Status == ShipmentStatus.Delayed ? "alert-danger" : "alert-dark")">
                            <strong>⚠️ @shipment.Status</strong> — This shipment is currently @shipment.Status.ToString().ToLower().
                        </div>
                    }

                    <div class="d-flex justify-content-between position-relative mb-3" style="margin-top: 10px;">
                        @for (int i = 0; i < steps.Length; i++)
                        {
                            var step = steps[i];
                            var isActive = !isSpecial && i <= currentIndex;
                            var isCurrent = !isSpecial && i == currentIndex;
                            <div class="text-center" style="flex: 1;">
                                <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-success text-white" : "bg-light text-muted border")"
                                     style="width: 40px; height: 40px; font-weight: bold; @(isCurrent ? "box-shadow: 0 0 0 3px rgba(25,135,84,0.5);" : "")">
                                    @(isActive ? "✓" : (i + 1).ToString())
                                </div>
                                <div class="small mt-1 @(isActive ? "fw-bold" : "text-muted")">@step</div>
                            </div>
                        }
                    </div>
                </div>

                <hr />

                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>
                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Shipped Date</dt>
                            <dd>@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>
                            <dt>Estimated Delivery</dt>
                            <dd>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</dd>
                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <dt>Actual Delivery</dt>
                                <dd>@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</dd>
                            }
                            <dt>Weight</dt>
                            <dd>@shipment.WeightKg.ToString("F1") kg</dd>
                        </dl>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public string? TrackingNumber { get; set; }

    private string searchInput = string.Empty;
    private Shipment? shipment;
    private bool loading;
    private bool searched;
    private string searchedNumber = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchInput = TrackingNumber;
            await DoSearch(TrackingNumber);
        }
    }

    private async Task Search()
    {
        if (!string.IsNullOrWhiteSpace(searchInput))
        {
            Navigation.NavigateTo($"/track/{Uri.EscapeDataString(searchInput.Trim())}");
        }
    }

    private async Task DoSearch(string trackingNumber)
    {
        loading = true;
        searched = false;
        shipment = null;
        StateHasChanged();

        searchedNumber = trackingNumber;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber);
        searched = true;
        loading = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }
}

@page "/shipments"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>All Shipments</PageTitle>

<div class="container mt-4">
    <h2>📋 All Shipments</h2>

    <div class="row mb-3">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Filter by tracking number or destination..."
                   @bind="filterText" @bind:event="oninput" />
        </div>
        <div class="col-md-6 text-end">
            <button class="btn btn-primary" @onclick="ToggleCreateForm">
                @(showCreateForm ? "Cancel" : "➕ Create Shipment")
            </button>
        </div>
    </div>

    @if (showCreateForm)
    {
        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title">New Shipment</h5>
                <div class="row g-3">
                    <div class="col-md-4">
                        <label class="form-label">Tracking Number</label>
                        <input type="text" class="form-control" @bind="newShipment.TrackingNumber" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Origin</label>
                        <input type="text" class="form-control" @bind="newShipment.Origin" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Destination</label>
                        <input type="text" class="form-control" @bind="newShipment.Destination" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Customer Email</label>
                        <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Description</label>
                        <input type="text" class="form-control" @bind="newShipment.Description" />
                    </div>
                    <div class="col-md-2">
                        <label class="form-label">Weight (kg)</label>
                        <input type="number" step="0.1" class="form-control" @bind="newShipment.WeightKg" />
                    </div>
                    <div class="col-md-2">
                        <label class="form-label">Est. Delivery Days</label>
                        <input type="number" class="form-control" @bind="estimatedDays" />
                    </div>
                    <div class="col-12">
                        <button class="btn btn-success" @onclick="CreateShipment">Create</button>
                    </div>
                </div>
            </div>
        </div>
    }

    @if (shipments is null)
    {
        <p><em>Loading shipments...</em></p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Weight (kg)</th>
                        <th>Update Status</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><a href="/track/@s.TrackingNumber">@s.TrackingNumber</a></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                            <td>@s.WeightKg.ToString("F1")</td>
                            <td>
                                <select class="form-select form-select-sm" value="@((int)s.Status)"
                                        @onchange="e => UpdateStatus(s, e)">
                                    @foreach (ShipmentStatus status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@((int)status)">@status</option>
                                    }
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        @if (!FilteredShipments.Any())
        {
            <div class="alert alert-info">No shipments match your filter.</div>
        }
    }
</div>

@code {
    private List<Shipment>? shipments;
    private string filterText = string.Empty;
    private bool showCreateForm;
    private Shipment newShipment = new();
    private int estimatedDays = 5;

    private IEnumerable<Shipment> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrWhiteSpace(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ToggleCreateForm() => showCreateForm = !showCreateForm;

    private async Task CreateShipment()
    {
        newShipment.ShippedDate = DateTime.UtcNow;
        newShipment.EstimatedDelivery = DateTime.UtcNow.AddDays(estimatedDays);
        newShipment.Status = ShipmentStatus.Pending;
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments?.Add(created);
        newShipment = new Shipment();
        estimatedDays = 5;
        showCreateForm = false;
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
            if (newStatus == ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-warning text-dark",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

