<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2>🔍 Track a Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number..."
                       @bind="searchInput" @bind:event="oninput" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="Search">Search</button>
            </div>
        </div>
    </div>

    @if (loading)
    {
        <p><em>Searching...</em></p>
    }
    else if (searched && shipment is null)
    {
        <div class="alert alert-warning">
            <strong>Shipment not found.</strong> No shipment matches tracking number "<strong>@searchedNumber</strong>".
        </div>
    }
    else if (shipment is not null)
    {
        <div class="card shadow-sm mb-4">
            <div class="card-header bg-dark text-white">
                <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
            </div>
            <div class="card-body">
                <!-- Status Progress -->
                <div class="mb-4">
                    <h6>Status Progress</h6>
                    @{
                        var steps = new[] { ShipmentStatus.Pending, ShipmentStatus.PickedUp, ShipmentStatus.InTransit, ShipmentStatus.OutForDelivery, ShipmentStatus.Delivered };
                        var currentIndex = Array.IndexOf(steps, shipment.Status);
                        var isSpecial = shipment.Status == ShipmentStatus.Delayed || shipment.Status == ShipmentStatus.Returned;
                    }

                    @if (isSpecial)
                    {
                        <div class="alert @(shipment.Status == ShipmentStatus.Delayed ? "alert-danger" : "alert-dark")">
                            <strong>⚠️ @shipment.Status</strong> — This shipment is currently @shipment.Status.ToString().ToLower().
                        </div>
                    }

                    <div class="d-flex justify-content-between position-relative mb-3" style="margin-top: 10px;">
                        @for (int i = 0; i < steps.Length; i++)
                        {
                            var step = steps[i];
                            var isActive = !isSpecial && i <= currentIndex;
                            var isCurrent = !isSpecial && i == currentIndex;
                            <div class="text-center" style="flex: 1;">
                                <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-success text-white" : "bg-light text-muted border")"
                                     style="width: 40px; height: 40px; font-weight: bold; @(isCurrent ? "box-shadow: 0 0 0 3px rgba(25,135,84,0.5);" : "")">
                                    @(isActive ? "✓" : (i + 1).ToString())
                                </div>
                                <div class="small mt-1 @(isActive ? "fw-bold" : "text-muted")">@step</div>
                            </div>
                        }
                    </div>
                </div>

                <hr />

                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>
                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Shipped Date</dt>
                            <dd>@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>
                            <dt>Estimated Delivery</dt>
                            <dd>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</dd>
                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <dt>Actual Delivery</dt>
                                <dd>@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</dd>
                            }
                            <dt>Weight</dt>
                            <dd>@shipment.WeightKg.ToString("F1") kg</dd>
                        </dl>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public string? TrackingNumber { get; set; }

    private string searchInput = string.Empty;
    private Shipment? shipment;
    private bool loading;
    private bool searched;
    private string searchedNumber = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchInput = TrackingNumber;
            await DoSearch(TrackingNumber);
        }
    }

    private async Task Search()
    {
        if (!string.IsNullOrWhiteSpace(searchInput))
        {
            Navigation.NavigateTo($"/track/{Uri.EscapeDataString(searchInput.Trim())}");
        }
    }

    private async Task DoSearch(string trackingNumber)
    {
        loading = true;
        searched = false;
        shipment = null;
        StateHasChanged();

        searchedNumber = trackingNumber;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber);
        searched = true;
        loading = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }
}

