 @page "/shipments"
 @attribute [Authorize]
 @inject IShipmentService ShipmentService

 <PageTitle>All Shipments</PageTitle>

 <div class="container mt-4">
     <h2>📋 All Shipments</h2>

     <div class="row mb-3">
         <div class="col-md-6">
             <input type="text" class="form-control" placeholder="Filter by tracking number or destination..."
                    @bind="filterText" @bind:event="oninput" />
         </div>
         <div class="col-md-6 text-end">
             <button class="btn btn-primary" @onclick="ToggleCreateForm">
                 @(showCreateForm ? "Cancel" : "➕ Create Shipment")
             </button>
         </div>
     </div>

     @if (showCreateForm)
     {
         <div class="card mb-4">
             <div class="card-body">
                 <h5 class="card-title">New Shipment</h5>
                 <div class="row g-3">
                     <div class="col-md-4">
                         <label class="form-label">Tracking Number</label>
                         <input type="text" class="form-control" @bind="newShipment.TrackingNumber" />
                     </div>
                     <div class="col-md-4">
                         <label class="form-label">Origin</label>
                         <input type="text" class="form-control" @bind="newShipment.Origin" />
                     </div>
                     <div class="col-md-4">
                         <label class="form-label">Destination</label>
                         <input type="text" class="form-control" @bind="newShipment.Destination" />
                     </div>
                     <div class="col-md-4">
                         <label class="form-label">Customer Email</label>
                         <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                     </div>
                     <div class="col-md-4">
                         <label class="form-label">Description</label>
                         <input type="text" class="form-control" @bind="newShipment.Description" />
                     </div>
                     <div class="col-md-2">
                         <label class="form-label">Weight (kg)</label>
                         <input type="number" step="0.1" class="form-control" @bind="newShipment.WeightKg" />
                     </div>
                     <div class="col-md-2">
                         <label class="form-label">Est. Delivery Days</label>
                         <input type="number" class="form-control" @bind="estimatedDays" />
                     </div>
                     <div class="col-12">
                         <button class="btn btn-success" @onclick="CreateShipment">Create</button>
                     </div>
                 </div>
             </div>
         </div>
     }

     @if (shipments is null)
     {
         <p><em>Loading shipments...</em></p>
     }
     else
     {
         <div class="table-responsive">
             <table class="table table-striped table-hover">
                 <thead class="table-dark">
                     <tr>
